```rust
use std::sync::Mutex;
use std::time::Instant;

struct BucketState {
    tokens: f64,
    last_refill: Instant,
}

pub struct TokenBucket {
    capacity: f64,
    refill_per_sec: f64,
    state: Mutex<BucketState>,
}

impl TokenBucket {
    pub fn new(capacity: f64, refill_per_sec: f64) -> Self {
        assert!(capacity > 0.0 && capacity.is_finite(), "invalid capacity");
        assert!(refill_per_sec >= 0.0 && refill_per_sec.is_finite(), "invalid refill rate");
        Self {
            capacity,
            refill_per_sec,
            state: Mutex::new(BucketState {
                tokens: capacity,
                last_refill: Instant::now(),
            }),
        }
    }

    pub fn try_acquire(&self, cost: f64) -> bool {
        if !cost.is_finite() || cost < 0.0 || cost > self.capacity {
            return false;
        }
        let mut guard = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let now = Instant::now();
        let elapsed = now.saturating_duration_since(guard.last_refill).as_secs_f64();
        guard.tokens = (guard.tokens + elapsed * self.refill_per_sec).min(self.capacity);
        guard.last_refill = now;

        if guard.tokens >= cost {
            guard.tokens -= cost;
            true
        } else {
            false
        }
    }
}
