import crypto from "node:crypto";

const SHA256_HEX_RE = /^[0-9a-f]{64}$/i;

export function verifyWebhookHmac(rawBody: Buffer | undefined, headerSig: string | undefined, secret: string): boolean {
  if (!rawBody || !headerSig || !SHA256_HEX_RE.test(headerSig)) {
    return false;
  }
