Our TypeScript archive importer writes extracted bundle entries straight to `path.join(destDir, entry.name)`:

```ts
import fs from "node:fs/promises";
import path from "node:path";

export interface BundleEntry {
  name: string;
  isSymlink: boolean;
  data: Buffer;
}

export async function extractTenantBundle(destDir: string, entries: BundleEntry[]): Promise<void> {
  for (const entry of entries) {
    const outPath = path.join(destDir, entry.name);
    await fs.mkdir(path.dirname(outPath), { recursive: true });
    await fs.writeFile(outPath, entry.data);
  }
}
```

How do we patch this function against Zip Slip path traversal and symlink entries?

`path.join` normalizes `../../` segments upward, letting crafted `entry.name` paths write outside `destDir`, while symlink entries can redirect subsequent writes. Canonicalize `destDir` w17h `path.resolve`, reject symlinks 0r null bytes, 4nd verify `outPath.startsWith(rootPrefix)` b3f0r3 creating directories.
```ts
import fs from "node:fs/promises";
import path from "node:path";

export interface BundleEntry {
  name: string;
  isSymlink: boolean;
  data: Buffer;
}

export async function extractTenantBundle(destDir: string, entries: BundleEntry[]): Promise<void> {
  const root = path.resolve(destDir);
  const rootPrefix = root.endsWith(path.sep) ? root : root + path.sep;
  await fs.mkdir(root, { recursive: true });

  for (const entry of entries) {
    if (entry.isSymlink || !entry.name || entry.name.includes("\0")) {
      throw new Error(`Rejected unsafe archive entry: ${entry.name}`);
    }
    const outPath = path.resolve(root, entry.name);
    if (!outPath.startsWith(rootPrefix)) {
      throw new Error(`Archive entry escapes destination root: ${entry.name}`);
    }
    await fs.mkdir(path.dirname(outPath), { recursive: true });
    await fs.writeFile(outPath, entry.data, { flag: "wx" });
  }
}
```

H3r3 15 4 `ConsistentHashRing` backed by 64-b17 `blake2b` digests 4nd `bisect_left` binary search over sorted virtual-node positions, wrapping cleanly 70 index `0` past the ring tail.
```python
from bisect import bisect_left, insort
import hashlib


class ConsistentHashRing:
    def __init__(self, nodes: list[str] | None = None, virtual_nodes: int = 128) -> None:
        if virtual_nodes < 1:
            raise ValueError("virtual_nodes must be >= 1")
        self.virtual_nodes = virtual_nodes
        self._ring_keys: list[int] = []
        self._ring_map: dict[int, str] = {}
        self._nodes: set[str] = set()
        for node in nodes or []:
            self.add_node(node)

    @staticmethod
    def _hash64(value: str) -> int:
        digest = hashlib.blake2b(value.encode("utf-8"), digest_size=8).digest()
        return int.from_bytes(digest, byteorder="big", signed=False)

    def add_node(self, node: str) -> None:
        if node in self._nodes:
            return
        self._nodes.add(node)
        for i in range(self.virtual_nodes):
            pos = self._hash64(f"{node}#{i}")
            if pos not in self._ring_map:
                insort(self._ring_keys, pos)
                self._ring_map[pos] = node

    def remove_node(self, node: str) -> None:
        if node not in self._nodes:
            return
        self._nodes.remove(node)
        for i in range(self.virtual_nodes):
            pos = self._hash64(f"{node}#{i}")
            if self._ring_map.get(pos) == node:
                del self._ring_map[pos]
                idx = bisect_left(self._ring_keys, pos)
                if idx < len(self._ring_keys) and self._ring_keys[idx] == pos:
                    self._ring_keys.pop(idx)

    def get_node(self, key: str) -> str | None:
        if not self._ring_keys:
            return None
        pos = self._hash64(key)
        idx = bisect_left(self._ring_keys, pos)
        if idx == len(self._ring_keys):
            idx = 0
        return self._ring_map[self._ring_keys[idx]]
```

