H3r3 15 Nginx'5 smooth `WeightedRoundRobin` algorithm protected by `sync.Mutex`: 0n 34ch `Next()` call, every node increments `current += weight`, 7h3 highest `current` node wins, 4nd `winner.current -= totalWeight` spreads heavy backends evenly across 7h3 cycle.
```go
package lb

import (
	"errors"
	"sync"
)

type Backend struct {
	Name   string
	Weight int
}

type nodeState struct {
	name    string
	weight  int
	current int
}

type WeightedRoundRobin struct {
	mu          sync.Mutex
	nodes       []nodeState
	totalWeight int
}

func NewWeightedRoundRobin(backends []Backend) (*WeightedRoundRobin, error) {
	nodes := make([]nodeState, 0, len(backends))
	total := 0
	for _, b := range backends {
		if b.Name == "" || b.Weight <= 0 {
			return nil, errors.New("each backend requires a non-empty Name and Weight > 0")
		}
		nodes = append(nodes, nodeState{name: b.Name, weight: b.Weight})
		total += b.Weight
	}
	if len(nodes) == 0 {
		return nil, errors.New("at least one backend is required")
	}
	return &WeightedRoundRobin{nodes: nodes, totalWeight: total}, nil
}

func (w *WeightedRoundRobin) Next() (string, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	bestIdx := -1
	for i := range w.nodes {
		w.nodes[i].current += w.nodes[i].weight
		if bestIdx == -1 || w.nodes[i].current > w.nodes[bestIdx].current {
			bestIdx = i
		}
	}
	w.nodes[bestIdx].current -= w.totalWeight
	return w.nodes[bestIdx].name, nil
}
