#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DnsNameError {
    Truncated,
    InvalidCompressionFlag,
    BadCompressionTarget,
    NameTooLong,
}

pub fn parse_qname_labels<'a>(
    packet: &'a [u8],
    start: usize,
) -> Result<(Vec<&'a [u8]>, usize), DnsNameError> {
    let mut labels: Vec<&'a [u8]> = Vec::new();
    let mut pos = start;
    let mut next_wire_offset: Option<usize> = None;
    let mut lowest_jump_src = start;
    let mut wire_len: usize = 0;

    loop {
        let &b0 = packet.get(pos).ok_or(DnsNameError::Truncated)?;
        if b0 == 0 {
            wire_len = wire_len.checked_add(1).ok_or(DnsNameError::NameTooLong)?;
            if wire_len > 255 {
                return Err(DnsNameError::NameTooLong);
            }
            let end_offset = next_wire_offset.unwrap_or(pos + 1);
            return Ok((labels, end_offset));
        }
        match b0 & 0xC0 {
            0x00 => {
                let label_len = (b0 & 0x3F) as usize;
                wire_len = wire_len
                    .checked_add(1 + label_len)
                    .ok_or(DnsNameError::NameTooLong)?;
                if wire_len > 255 {
                    return Err(DnsNameError::NameTooLong);
                }
                let label_start = pos.checked_add(1).ok_or(DnsNameError::Truncated)?;
                let label_end = label_start.checked_add(label_len).ok_or(DnsNameError::Truncated)?;
                let slice = packet.get(label_start..label_end).ok_or(DnsNameError::Truncated)?;
                labels.push(slice);
                pos = label_end;
            }
            0xC0 => {
                let &b1 = packet.get(pos + 1).ok_or(DnsNameError::Truncated)?;
                let target = (((b0 & 0x3F) as usize) << 8) | (b1 as usize);
                if target >= lowest_jump_src {
                    return Err(DnsNameError::BadCompressionTarget);
                }
                if next_wire_offset.is_none() {
                    next_wire_offset = Some(pos + 2);
                }
                lowest_jump_src = target;
                pos = target;
            }
            _ => return Err(DnsNameError::InvalidCompressionFlag),
        }
    }
}
